sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_pattern;
uniform float amzp_alphaComp;
uniform float amzp_scaleComp;
uniform float amzp_fallAngle;
uniform float2 amzp_position;
uniform float2 amzp_space;
uniform float amzp_amount;
uniform float amzp_dropSize;
uniform float amzp_headLen;
uniform float amzp_headTaper;
uniform float amzp_sizeVar;
uniform float amzp_fallSpeed;
uniform float amzp_speedVar;
uniform float amzp_density;
uniform float amzp_interval;
uniform float amzp_seed;
uniform float amzp_tailLen;
uniform float amzp_tailWidth;
uniform float amzp_tailSmear;
uniform float amzp_tailBeads;
uniform float amzp_tailFade;
uniform float amzp_wigAmt;
uniform float amzp_wigFreq;
uniform float amzp_wigRand;
uniform float amzp_pause;
uniform float amzp_pauseRate;
uniform float amzp_pauseRand;
uniform float amzp_refr;
uniform float amzp_magnify;
uniform float amzp_edgeShade;
uniform float amzp_shine;
layout(color) uniform half4 amzp_shineColor;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    float2 gW;
    float gAng;
    float2 rotv(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hs(float a, float b, float k) { return fract(sin(a * 127.1 + b * 311.7 + k * 74.7 + amzp_seed * 3.17) * 43758.5453); }
    float4 srcQ(float2 q) {
        float2 uv = clamp(rotv(q, gAng) / gW + 0.5, float2(0.0), float2(1.0));
        return amzTexture(0, l2s(uv));
    }
    float pathX(float yd, float ph, float amp, float f) {
        return amp * (0.7 * sin(yd * f + ph) + 0.3 * sin(yd * f * 2.31 + ph * 1.7 + 1.3));
    }
    void amzRender() {
        float2 W = layer;
        gW = W;
        gAng = radians(amzp_fallAngle);
        float M = min(W.x, W.y);
        float2 p = (amzLayerNorm() - 0.5) * W;
        float2 q = rotv(p, -gAng);
        float Sc = max(amzp_scaleComp, 0.01);
        float2 qp = (q - rotv(float2(amzp_position.x, -amzp_position.y), -gAng)) / Sc;
        float cs = abs(cos(gAng)), sn = abs(sin(gAng));
        float ex = cs * W.x + sn * W.y;
        float ey = sn * W.x + cs * W.y;
        float yd = -qp.y;
        float T = amzp_progress * 10.0 + ((amzp_autop>0.5) ? time * amzp_autoSpeed : 0.0);
        float N = max(floor(amzp_amount + 0.5), 1.0);
        float2 dist = max(amzp_space, float2(0.05));
        float laneW = ex / N * dist.x;
        float li = floor(qp.x / laneW + 0.5);
        float R0 = max(amzp_dropSize, 0.0005) * M;
        float tail = max(amzp_tailLen, 0.0) * ey;
        float wAmp = max(amzp_wigAmt, 0.0) * M;
        float wF = max(amzp_wigFreq, 0.0) * 6.2831853 / ey;
        float rate = max(amzp_pauseRate, 0.05);
        float pz = clamp(amzp_pause, 0.0, 0.95);
        float2 off = float2(0.0);
        float hMax = 0.0;
        float sMax = 0.0;
        float2 hv = float2(0.0);
        float hHead = 0.0;
        float sm = 0.0;
        float elong = max(amzp_headLen, 0.3);
        float taper = clamp(amzp_headTaper, 0.0, 1.0);
        for (int k = -4; k <= 4; k++) {
            if (abs(float(k)) > amzp_quality) continue;
            float j = li + float(k);
            float a1 = hs(j, 1.0, 1.0), a2 = hs(j, 2.0, 2.0), a3 = hs(j, 3.0, 3.0), a4 = hs(j, 4.0, 4.0);
            float ph;
            if (int(amzp_pattern) == 1) ph = fract(j * 0.6180339);
            else if (int(amzp_pattern) == 2) ph = fract(j / N);
            else if (int(amzp_pattern) == 3) ph = 0.0;
            else if (int(amzp_pattern) == 4) ph = mod(j, 2.0) * 0.5;
            else ph = a1;
            float jit = (int(amzp_pattern) == 0) ? (a2 - 0.5) * 0.6 : 0.0;
            float laneX = (j + jit) * laneW;
            float spd = max(amzp_fallSpeed, 0.0) * ey * (1.0 + (a3 - 0.5) * 1.6 * amzp_speedVar);
            float tm;
            if (pz <= 0.0) tm = T;
            else {
                float u = T * rate + a4 * amzp_pauseRand;
                float e = fract(u);
                tm = (floor(u) + smoothstep(0.0, 1.0 - pz, e) - a4 * amzp_pauseRand) / rate;
            }
            float Lc = max((amzp_interval * ey + tail + 2.0 * R0 * elong) * dist.y, 4.0 * R0 * elong);
            float tl = min(tail, max(Lc - 2.2 * R0 * elong, 0.0));
            float S = spd * tm + ph * Lc - 0.5 * ey - 2.0 * R0 * elong;
            float n = floor((S - yd) / Lc);
            for (int c = 0; c < 2; c++) {
                float nn = n + float(c);
                float hy = S - nn * Lc;
                float d = hy - yd;
                float b0 = hs(j, nn, 5.0), b1 = hs(j, nn, 6.0), b2 = hs(j, nn, 7.0), b3 = hs(j, nn, 8.0), b4 = hs(j, nn, 9.0);
                if (b0 > amzp_density) continue;
                float r = R0 * (1.0 + (b1 - 0.5) * 1.6 * amzp_sizeVar);
                float wph = mix(j * 1.7, b2 * 6.2831853, amzp_wigRand);
                float wa = wAmp * (1.0 + (b3 - 0.5) * 1.2 * amzp_wigRand);
                float cx = laneX + pathX(hy, wph, wa, wF);
                float2 rel = float2(qp.x - cx, qp.y + hy);
                float vy = rel.y / (r * elong);
                float wx = 1.0 - taper * 0.55 * smoothstep(-0.4, 1.0, vy);
                float2 v = float2(rel.x / (r * wx), vy);
                float dd = dot(v, v);
                if (dd < 1.0) {
                    float s = 1.0 - dd;
                    float H = s * s;
                    off -= v * s * (2.2 * 0.9 * amzp_refr * r);
                    off -= rel * (amzp_magnify * H);
                    if (H > hMax) { hMax = H; sMax = s; }
                    if (H > hHead) { hHead = H; hv = v; }
                }
                if (c == 0 && d > 0.0 && d < tl) {
                    float f = d / tl;
                    float tx = laneX + pathX(yd, wph, wa, wF);
                    float w = r * amzp_tailWidth * pow(1.0 - f, 0.6);
                    float bump = 1.0 - abs(fract(d / (r * 1.8) + b4) * 2.0 - 1.0);
                    w *= mix(1.0, 0.15 + 0.85 * bump, amzp_tailBeads * smoothstep(0.0, 3.0 * r, d));
                    float dx = (qp.x - tx) / max(w, 0.0001);
                    if (w > 0.25 && abs(dx) < 1.0) {
                        float s = 1.0 - dx * dx;
                        float fd = 1.0 - amzp_tailFade * f;
                        float H = s * s * fd;
                        off.x -= dx * s * fd * (2.2 * 0.7 * amzp_refr * w);
                        sm = max(sm, amzp_tailSmear * min(d, r * 6.0) * H);
                        if (H > hMax) { hMax = H; sMax = s * fd; }
                    }
                }
            }
        }
        float4 col;
        if (hMax <= 0.0) {
            col = amzTexture(0, amzScreenNorm());
        } else {
            float2 qc = q + off * Sc;
            if (sm > 0.0) {
                float ns = 2.0 + 2.0 * amzp_quality;
                float4 acc = float4(0.0);
                for (int s = 0; s < 10; s++) {
                    if (float(s) >= ns) break;
                    float t = float(s) / (ns - 1.0);
                    acc += srcQ(qc + float2(0.0, sm * Sc * t));
                }
                col = acc / ns;
            } else {
                col = srcQ(qc);
            }
            float ring = smoothstep(0.0, 0.18, sMax) * (1.0 - smoothstep(0.18, 0.6, sMax));
            col.rgb *= 1.0 - amzp_edgeShade * ring;
            if (amzp_shine > 0.0 && hHead > 0.0) {
                float2 dl = hv - float2(-0.35, 0.3);
                float sp = exp(-dot(dl, dl) / 0.035) * smoothstep(0.0, 0.3, hHead);
                col.rgb += amzp_shineColor.rgb * amzp_shine * sp * col.a;
            }
        }
        amzOutput = mix(amzTexture(0, amzScreenNorm()), col, clamp(amzp_alphaComp, 0.0, 1.0));
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
